$ErrorActionPreference = "Stop"

$root = Get-Location
$frontend = Join-Path $root "frontend"

if (-not (Test-Path (Join-Path $root ".git"))) {
    throw "Run this script from the SakhtYar repository root."
}
if (-not (Test-Path (Join-Path $frontend "package.json"))) {
    throw "frontend\package.json was not found."
}

function Read-Utf8([string]$Path) {
    [System.IO.File]::ReadAllText(
        $Path,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

function Write-Utf8([string]$Path, [string]$Content) {
    $parent = Split-Path $Path -Parent
    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }
    [System.IO.File]::WriteAllText(
        $Path,
        $Content,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

function Write-Base64File([string]$RelativePath, [string]$Base64) {
    $path = Join-Path $root $RelativePath
    $parent = Split-Path $path -Parent
    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }
    [System.IO.File]::WriteAllBytes(
        $path,
        [Convert]::FromBase64String($Base64)
    )
}

function Stop-SakhtYarVite5175 {
    $listeners = @(
        Get-NetTCPConnection -LocalPort 5175 -State Listen -ErrorAction SilentlyContinue
    )
    foreach ($listener in $listeners) {
        $pidValue = $listener.OwningProcess
        $proc = Get-CimInstance Win32_Process -Filter "ProcessId = $pidValue" -ErrorAction SilentlyContinue
        $cmd = if ($proc) { [string]$proc.CommandLine } else { "" }

        if (
            ($cmd -match 'vite' -or $cmd -match 'node_modules[\\/]+vite') -and
            ($cmd -match 'SakhtYar' -or $cmd -match 'ChatGPT_Projects')
        ) {
            Write-Host "Stopping stale SakhtYar Vite PID=$pidValue" -ForegroundColor Yellow
            Stop-Process -Id $pidValue -Force
        }
    }
    Start-Sleep -Milliseconds 400
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " SakhtYar UI V5.6 - Login + Brand + Gallery + Polish" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $root ".local\patch-backups\ui-v5.6-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$filesToBackup = @(
    "frontend\src\app\AppShell.tsx",
    "frontend\src\pages\LoginPage.tsx",
    "frontend\src\pages\CaseDetailPage.tsx",
    "frontend\src\features\case\OwnersPanel.tsx",
    "frontend\src\features\case\ProjectGalleryPanel.tsx",
    "frontend\src\features\case\AssistantPanel.tsx",
    "frontend\src\styles\global.css"
)

Write-Host ""
Write-Host "[1/8] Backup..." -ForegroundColor Cyan
foreach ($relative in $filesToBackup) {
    $source = Join-Path $root $relative
    if (Test-Path $source) {
        $dest = Join-Path $backupRoot $relative
        New-Item -ItemType Directory -Force -Path (Split-Path $dest -Parent) | Out-Null
        Copy-Item $source $dest -Force
    }
}
Write-Host "Backup created: $backupRoot" -ForegroundColor DarkGray

Write-Host ""
Write-Host "[2/8] Writing corrected brand mark and pages..." -ForegroundColor Cyan
Write-Base64File "frontend\public\assets\sakhtyar\brand\sakhtyar-mark.svg" ""
Write-Base64File "frontend\src\app\AppShell.tsx" ""
Write-Base64File "frontend\src\pages\LoginPage.tsx" ""
Write-Base64File "frontend\src\pages\CaseDetailPage.tsx" ""
Write-Base64File "frontend\src\features\case\ProjectGalleryPanel.tsx" ""
Write-Base64File "frontend\src\features\case\OwnersPanel.tsx" ""

Write-Host "Brand mark and requested pages written." -ForegroundColor Green

Write-Host ""
Write-Host "[3/8] Polishing Smart Assistant..." -ForegroundColor Cyan
$assistantPath = Join-Path $frontend "src\features\case\AssistantPanel.tsx"
if (Test-Path $assistantPath) {
    $assistant = Read-Utf8 $assistantPath

    if (-not $assistant.Contains('sakhtyar-assistant-v56')) {
        $assistant = [regex]::Replace(
            $assistant,
            'return \(\s*<Stack spacing=\{2\}>',
            'return (`r`n    <Stack spacing={2} className="sakhtyar-assistant-v56">',
            1
        )

        $assistant = $assistant.Replace(
            '<Card variant="outlined">',
            '<Card variant="outlined" className="sakhtyar-assistant-card">'
        )

        Write-Utf8 $assistantPath $assistant
        Write-Host "Smart Assistant classes applied." -ForegroundColor Green
    } else {
        Write-Host "Smart Assistant already polished." -ForegroundColor DarkGreen
    }
} else {
    Write-Host "WARNING: AssistantPanel.tsx not found." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "[4/8] Installing 10 unique high-resolution project images..." -ForegroundColor Cyan
$assets = @{}
$assets["frontend/public/assets/sakhtyar/projects/project-01.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-02.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-03.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-04.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-05.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-06.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-07.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-08.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-09.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-10.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/heroes/login-hero.jpg"] = ""
foreach ($relative in $assets.Keys) {
    Write-Base64File $relative $assets[$relative]
}
Write-Host "10 project images + login hero installed offline." -ForegroundColor Green

Write-Host ""
Write-Host "[5/8] Applying visual CSS..." -ForegroundColor Cyan
$cssPath = Join-Path $frontend "src\styles\global.css"
$globalCss = Read-Utf8 $cssPath

$globalCss = [regex]::Replace(
    $globalCss,
    '(?s)/\* === SakhtYar UI V5\.6 START === \*/.*?/\* === SakhtYar UI V5\.6 END === \*/',
    ''
)

$globalCss = $globalCss.TrimEnd() + "`r`n`r`n" + @'
/* === SakhtYar UI V5.6 START === */

html,
body,
button,
input,
textarea,
select,
.ant-typography,
.ant-btn,
.ant-input,
.ant-select,
.ant-table,
.ant-tabs {
  font-family:
    "B Nazanin",
    "IRNazanin",
    "Vazirmatn",
    Tahoma,
    Arial,
    sans-serif !important;
}

/* Brand mark: Persian wordmark is live HTML text,
   so Persian dots remain correct on every screen. */
.sakhtyar-brand-v56 {
  gap: 10px !important;
}

.sakhtyar-brand-mark {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  box-shadow:
    0 10px 22px rgba(22, 93, 215, .18);
}

.sakhtyar-brand-v56 .sakhtyar-brand-copy strong {
  font-size: 23px !important;
  line-height: 1.05;
}

.sakhtyar-brand-v56 .sakhtyar-brand-copy small {
  font-size: 10px !important;
}

.sakhtyar-logout-button {
  min-width: 38px !important;
  width: 38px !important;
  height: 38px !important;
  padding: 0 !important;
  border-radius: 50% !important;
  font-size: 17px !important;
}

/* Login */
.sakhtyar-login-v56 {
  min-height: 100vh;
  display: grid;
  grid-template-columns:
    minmax(640px, 1.12fr)
    minmax(430px, .88fr);
  background: #eef3f9;
}

.sakhtyar-login-v56__hero {
  position: relative;
  min-height: 100vh;
  background:
    url("/assets/sakhtyar/heroes/login-hero.jpg")
    center / cover no-repeat;
  overflow: hidden;
}

.sakhtyar-login-v56__shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(5, 28, 61, .82) 0%,
      rgba(7, 35, 73, .72) 43%,
      rgba(13, 44, 82, .36) 72%,
      rgba(238, 243, 249, .08) 100%
    ),
    radial-gradient(
      circle at 15% 15%,
      rgba(74, 180, 255, .18),
      transparent 32%
    );
}

.sakhtyar-login-v56__brand {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  width: min(600px, 82%);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 50px 62px;
  color: #fff;
}

.sakhtyar-login-v56__brandline {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 24px;
}

.sakhtyar-login-v56__mark {
  width: 76px;
  height: 76px;
  border-radius: 22px;
  box-shadow:
    0 18px 40px rgba(0, 0, 0, .22);
}

.sakhtyar-login-v56__wordmark {
  color: #fff;
  font-size: 34px;
  font-weight: 900;
  line-height: 1.1;
}

.sakhtyar-login-v56__subbrand {
  margin-top: 5px;
  color: rgba(255, 255, 255, .76);
  font-size: 13px;
}

.sakhtyar-login-v56__brand .ant-typography {
  color: #fff;
}

.sakhtyar-login-v56__brand h1 {
  margin: 0 0 14px !important;
  font-size:
    clamp(38px, 3.9vw, 56px) !important;
  font-weight: 900 !important;
  line-height: 1.35 !important;
  letter-spacing: -.015em;
}

.sakhtyar-login-v56__brand p {
  max-width: 500px;
  margin: 0 !important;
  color:
    rgba(255, 255, 255, .88) !important;
  font-size: 16px !important;
  line-height: 2 !important;
}

.sakhtyar-login-v56__features {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 22px;
}

.sakhtyar-login-v56__features span {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  padding: 7px 13px;
  border:
    1px solid rgba(255, 255, 255, .20);
  border-radius: 999px;
  background:
    rgba(255, 255, 255, .12);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  backdrop-filter: blur(9px);
}

.sakhtyar-login-v56__panel {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 28px;
  background:
    radial-gradient(
      circle at 75% 10%,
      rgba(61, 132, 255, .10),
      transparent 27%
    ),
    #f7faff;
}

.sakhtyar-login-v56__card {
  width: min(440px, 100%);
  border-radius: 28px !important;
  border:
    1px solid rgba(215, 225, 238, .85) !important;
  box-shadow:
    0 28px 70px rgba(25, 56, 96, .14) !important;
}

.sakhtyar-login-v56__card .ant-card-body {
  padding: 28px !important;
}

.sakhtyar-login-v56__cardhead {
  margin-bottom: 18px;
  text-align: center;
}

.sakhtyar-login-v56__cardmark {
  width: 72px;
  height: 72px;
  border-radius: 20px;
  margin-bottom: 8px;
}

.sakhtyar-login-v56__cardword {
  color: #16427d;
  font-size: 27px;
  font-weight: 900;
  line-height: 1.2;
}

.sakhtyar-login-v56__cardhead h2 {
  margin: 12px 0 5px !important;
  color: #173b6e;
  font-size: 23px !important;
}

.sakhtyar-login-v56__cardhead
.ant-typography-secondary {
  font-size: 12px;
}

.sakhtyar-login-v56__card
.ant-form-item {
  margin-bottom: 14px !important;
}

.sakhtyar-login-v56__card
.ant-form-item-label {
  padding-bottom: 5px !important;
}

.sakhtyar-login-v56__card
.ant-form-item-label label {
  color: #314760;
  font-size: 12px;
  font-weight: 800;
}

.sakhtyar-login-v56__card
.ant-input-affix-wrapper {
  min-height: 46px !important;
  border-radius: 14px !important;
}

.sakhtyar-login-v56__submit,
.sakhtyar-login-v56__register {
  min-height: 45px !important;
  border-radius: 14px !important;
}

.sakhtyar-login-v56__divider {
  position: relative;
  margin: 15px 0;
  text-align: center;
  color: #a0acbb;
  font-size: 11px;
}

.sakhtyar-login-v56__divider::before {
  content: "";
  position: absolute;
  top: 50%;
  inset-inline: 0;
  height: 1px;
  background: #e6ecf4;
}

.sakhtyar-login-v56__divider span {
  position: relative;
  z-index: 1;
  padding-inline: 10px;
  background: #fff;
}

/* Project images */
.sakhtyar-project-cover {
  background: #e6edf5 !important;
}

.sakhtyar-project-cover img,
.sakhtyar-case-split-media__image {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover !important;
  object-position: center !important;
  image-rendering: auto;
  transform: translateZ(0);
}

.sakhtyar-project-card-cards
.sakhtyar-project-cover {
  height: 210px !important;
}

.sakhtyar-project-card-compact
.sakhtyar-project-cover {
  height: 164px !important;
}

.sakhtyar-case-page-v56
.sakhtyar-case-split-hero {
  min-height: 248px !important;
}

.sakhtyar-case-page-v56
.sakhtyar-case-split-media {
  min-height: 248px !important;
}

.sakhtyar-case-page-v56
.sakhtyar-case-split-info {
  padding: 24px 28px !important;
}

/* Gallery */
.sakhtyar-gallery-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.sakhtyar-gallery-uploader
.ant-card-body {
  padding: 18px !important;
}

.sakhtyar-gallery-uploader__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.sakhtyar-gallery-uploader__header h4 {
  margin: 0 0 4px !important;
}

.sakhtyar-gallery-uploader__controls {
  display: grid;
  grid-template-columns:
    220px
    minmax(240px, 1fr)
    150px;
  gap: 10px;
}

.sakhtyar-gallery-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fill,
      minmax(260px, 1fr)
    );
  gap: 14px;
}

.sakhtyar-gallery-card {
  overflow: hidden;
}

.sakhtyar-gallery-card__cover {
  all: unset;
  display: block;
  width: 100%;
  height: 190px;
  cursor: zoom-in;
  background: #edf3fa;
}

.sakhtyar-gallery-card__cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sakhtyar-gallery-card__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

/* Owners */
.sakhtyar-owners-v56 {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sakhtyar-owners-v56__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.sakhtyar-owners-v56__head h4 {
  margin: 0 0 4px !important;
}

.sakhtyar-owner-summary-card
.ant-card-body {
  min-height: 96px;
  padding: 14px 16px !important;
  display: flex;
  align-items: center;
}

.sakhtyar-owner-summary-card
.ant-statistic-content {
  font-size: 22px !important;
}

.sakhtyar-owner-primary {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.sakhtyar-owner-primary small {
  color: #8491a5;
  font-size: 11px;
}

.sakhtyar-owner-primary strong {
  color: #173d72;
  font-size: 17px;
}

.sakhtyar-owner-progress-card
.ant-card-body {
  padding: 12px 16px !important;
}

.sakhtyar-owner-progress-title {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.sakhtyar-owner-table-card
.ant-card-body {
  padding: 10px !important;
}

.sakhtyar-owner-table-card
.ant-table-thead > tr > th,
.sakhtyar-owner-table-card
.ant-table-tbody > tr > td {
  padding: 10px 12px !important;
}

.sakhtyar-owner-avatar {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  color: #2268e8;
  background: #edf4ff;
}

/* Assistant */
.sakhtyar-assistant-v56 {
  position: relative;
}

.sakhtyar-assistant-v56
.sakhtyar-assistant-card {
  border:
    1px solid #e1e8f2 !important;
  border-radius: 20px !important;
  box-shadow:
    0 10px 28px rgba(37, 65, 101, .055);
  overflow: hidden;
}

.sakhtyar-assistant-v56
.sakhtyar-assistant-card:first-child {
  background:
    linear-gradient(
      135deg,
      rgba(236, 244, 255, .94),
      #fff 52%
    );
}

.sakhtyar-assistant-v56
.MuiChip-root {
  border-radius: 999px !important;
}

.sakhtyar-assistant-v56
.MuiButton-contained {
  box-shadow:
    0 9px 20px rgba(37, 99, 235, .18);
}

/* Account equal-height cards */
.sakhtyar-account-page-v54
.ant-row > .ant-col {
  display: flex;
}

.sakhtyar-account-page-v54
.ant-row > .ant-col >
.sakhtyar-account-card {
  width: 100%;
  height: 100%;
}

/* Subtle animation */
@keyframes sakhtyarSoftFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-3px);
  }
}

.sakhtyar-brand-mark {
  animation:
    sakhtyarSoftFloat
    3.8s
    ease-in-out
    infinite;
}

@media (
  prefers-reduced-motion:
  reduce
) {
  .sakhtyar-brand-mark {
    animation: none !important;
  }
}

@media (max-width: 1100px) {
  .sakhtyar-login-v56 {
    grid-template-columns: 1fr;
  }

  .sakhtyar-login-v56__hero {
    min-height: 390px;
  }

  .sakhtyar-login-v56__brand {
    min-height: 390px;
    width: 100%;
    padding: 34px 28px;
    justify-content: flex-end;
  }

  .sakhtyar-gallery-uploader__controls {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .sakhtyar-login-v56__hero {
    min-height: 300px;
  }

  .sakhtyar-login-v56__brand h1 {
    font-size: 30px !important;
  }

  .sakhtyar-login-v56__mark {
    width: 60px;
    height: 60px;
  }

  .sakhtyar-login-v56__wordmark {
    font-size: 27px;
  }
}

/* === SakhtYar UI V5.6 END === */
'@

Write-Utf8 $cssPath $globalCss
Write-Host "Visual polish applied." -ForegroundColor Green

Write-Host ""
Write-Host "[6/8] Verifying duplicate Map tab is not present..." -ForegroundColor Cyan
$detailText = Read-Utf8 (Join-Path $frontend "src\pages\CaseDetailPage.tsx")
if ($detailText.Contains("label: 'نقشه'")) {
    throw "Standalone Map tab still exists."
}
Write-Host "Only Property > Location map remains." -ForegroundColor Green

Write-Host ""
Write-Host "[7/8] Clearing Vite cache..." -ForegroundColor Cyan
Stop-SakhtYarVite5175

foreach ($path in @(
    (Join-Path $frontend "node_modules\.vite"),
    (Join-Path $frontend "dist")
)) {
    if (Test-Path $path) {
        Remove-Item $path -Recurse -Force
    }
}

Write-Host ""
Write-Host "[8/8] Building frontend..." -ForegroundColor Cyan
Push-Location $frontend
try {
    npm run build
    if ($LASTEXITCODE -ne 0) {
        throw "Frontend build failed."
    }
}
finally {
    Pop-Location
}

git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check failed."
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host " DONE - SakhtYar UI V5.6 applied successfully" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Included:" -ForegroundColor Cyan
Write-Host " - Correct Persian wordmark rendered as live text (dots remain correct)"
Write-Host " - New professional building mark in header and login"
Write-Host " - Complete login redesign with readable copy and full image background"
Write-Host " - 10 unique high-resolution project images"
Write-Host " - Sharper project detail hero image rendering"
Write-Host " - Persistent project image gallery backed by Documents/MinIO"
Write-Host " - Compact Owners summary cards and table"
Write-Host " - Smart Assistant visual polish"
Write-Host " - Equal-height Account profile/password cards"
Write-Host " - Logout changed to a clear power-button style"
Write-Host " - Duplicate standalone Map tab kept removed"
Write-Host ""
Write-Host "Next:" -ForegroundColor Yellow
Write-Host "  cd D:\ChatGPT_Projects\SakhtYar\source\frontend"
Write-Host "  npm run dev"
Write-Host ""
Write-Host "Then press Ctrl + F5 in the browser."
Write-Host ""
Write-Host "No Docker volume was deleted. No Git commit or push was performed." -ForegroundColor DarkGray
